#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n + 1);
    array<int, 101> frequency{};

    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        ++frequency[a[i]];
    }

    int mostFrequent = 1;
    for (int value = 2; value <= 100; ++value) {
        if (frequency[value] > frequency[mostFrequent]) {
            mostFrequent = value;
        }
    }

    if (frequency[mostFrequent] == 2) {
        cout << n << '\n';
        return 0;
    }

    int answer = 0;
    vector<int> firstOccurrence(2 * n + 1);

    for (int value = 1; value <= 100; ++value) {
        if (value == mostFrequent || frequency[value] == 0) {
            continue;
        }

        fill(firstOccurrence.begin(), firstOccurrence.end(), -1);

        int prefixSum = 0;
        firstOccurrence[n] = 0;

        for (int i = 1; i <= n; ++i) {
            if (a[i] == mostFrequent) {
                ++prefixSum;
            } else if (a[i] == value) {
                --prefixSum;
            }

            int index = prefixSum + n;
            if (firstOccurrence[index] != -1) {
                answer = max(answer, i - firstOccurrence[index]);
            } else {
                firstOccurrence[index] = i;
            }
        }
    }

    cout << answer << '\n';
    return 0;
}

